const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;

pub const HTRNode = struct {
    phase: f32,
    amplitude: f32,
    resonance: f32,
    topological_charge: i32,
    entanglement_factor: f32,
};

pub const TopologyMatrix = struct {
     []f32,
    rows: usize,
    cols: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, rows: usize, cols: usize) !TopologyMatrix {
        const data = try allocator.alloc(f32, rows * cols);
        for (data) |*v| v.* = 0.0;
        return TopologyMatrix{
            .data = data,
            .rows = rows,
            .cols = cols,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *TopologyMatrix) void {
        self.allocator.free(self.data);
    }

    pub fn get(self: *const TopologyMatrix, row: usize, col: usize) f32 {
        return self.data[row * self.cols + col];
    }

    pub fn set(self: *TopologyMatrix, row: usize, col: usize, val: f32) void {
        self.data[row * self.cols + col] = val;
    }
};

pub const HTRState = struct {
    nodes: []HTRNode,
    weights: TopologyMatrix,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize) !HTRState {
        const nodes = try allocator.alloc(HTRNode, dim);
        for (nodes, 0..) |*n, i| {
            n.phase = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(dim));
            n.amplitude = 1.0;
            n.resonance = 0.0;
            n.topological_charge = @as(i32, @intCast(i % 3)) - 1;
            n.entanglement_factor = 0.5;
        }
        var weights = try TopologyMatrix.init(allocator, dim, dim);
        for (0..dim) |i| {
            for (0..dim) |j| {
                const fi = @as(f32, @floatFromInt(i));
                const fj = @as(f32, @floatFromInt(j));
                const diff = fi - fj;
                const abs_diff = if (diff < 0.0) -diff else diff;
                weights.set(i, j, @exp(-abs_diff * 0.1));
            }
        }
        return HTRState{
            .nodes = nodes,
            .weights = weights,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *HTRState) void {
        self.allocator.free(self.nodes);
        self.weights.deinit();
    }

    pub fn forward(self: *HTRState, input: []const f32, output: []f32) void {
        const dim = self.nodes.len;
        for (0..dim) |i| {
            var state_update: f32 = 0.0;
            for (0..dim) |j| {
                state_update += self.weights.get(i, j) * self.nodes[j].resonance;
            }
            const in_val: f32 = if (i < input.len) input[i] else 0.0;
            const n = &self.nodes[i];
            const raw_phase = n.phase + in_val + state_update * 0.01;
            const two_pi = 2.0 * math.pi;
            n.phase = raw_phase - two_pi * @floor(raw_phase / two_pi);
            const abs_in = if (in_val < 0.0) -in_val else in_val;
            n.amplitude = if (n.amplitude + abs_in * 0.001 < 2.0) n.amplitude + abs_in * 0.001 else 2.0;
            n.resonance = n.amplitude * @sin(n.phase) * @as(f32, @floatFromInt(n.topological_charge));
            if (i < output.len) {
                output[i] = n.resonance;
            }
        }
    }

    pub fn braid_anyons(self: *HTRState, index_a: usize, index_b: usize) void {
        if (index_a >= self.nodes.len or index_b >= self.nodes.len) return;
        const n_a = &self.nodes[index_a];
        const n_b = &self.nodes[index_b];
        const temp_phase = n_a.phase;
        n_a.phase = n_b.phase + math.pi / 2.0;
        n_b.phase = temp_phase - math.pi / 2.0;
        n_a.entanglement_factor += 0.1;
        n_b.entanglement_factor += 0.1;
    }
};

pub const JaideCore = struct {
    state: HTRState,

    pub fn init(allocator: Allocator, width: usize) !JaideCore {
        return JaideCore{
            .state = try HTRState.init(allocator, width),
        };
    }

    pub fn deinit(self: *JaideCore) void {
        self.state.deinit();
    }

    pub fn process_token_stream(self: *JaideCore, stream: []const f32, out_stream: []f32) void {
        const width = self.state.nodes.len;
        var chunk_start: usize = 0;
        while (chunk_start < stream.len) {
            const chunk_end = if (chunk_start + width < stream.len) chunk_start + width else stream.len;
            const in_chunk = stream[chunk_start..chunk_end];
            const out_end = if (chunk_end < out_stream.len) chunk_end else out_stream.len;
            const out_chunk = if (chunk_start < out_end) out_stream[chunk_start..out_end] else out_stream[0..0];
            self.state.forward(in_chunk, out_chunk);
            if (chunk_end > 1) {
                self.state.braid_anyons((chunk_end - 1) % width, (chunk_end - 2) % width);
            }
            chunk_start += width;
        }
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var jaide = try JaideCore.init(allocator, 4096);
    defer jaide.deinit();

    const seq_len: usize = 8192;

    const input = try allocator.alloc(f32, seq_len);
    defer allocator.free(input);

    const output = try allocator.alloc(f32, seq_len);
    defer allocator.free(output);

    for (input, 0..) |*v, i| {
        v.* = @as(f32, @floatFromInt(i % 256)) / 256.0;
    }
    for (output) |*v| v.* = 0.0;

    jaide.process_token_stream(input, output);

    var sum: f64 = 0.0;
    for (output) |v| {
        sum += @as(f64, v);
    }

    const stdout = std.io.getStdOut().writer();
    try stdout.print("HTR output sum: {d:.6}\n", .{sum});
}

